-- =====================================================================
-- Migration 085: cf-warp v3 — WARP profile pool + rotation (no wgcf)
-- =====================================================================
-- Replaces the single-profile wgcf install with a native (PHP/bash) WARP
-- registration that maintains a pool of profiles and rotates the active one
-- on health failure / HTTP 429 / a traffic threshold, to dodge per-device
-- rate limits and blocks. netns/veth/policy-routing (awg2warp, table 51888,
-- mark 0x2cf2, MTU 1280) preserved. Scripts embedded via FROM_BASE64.
-- Idempotent: a plain UPDATE of the cf-warp protocol row.
-- =====================================================================

UPDATE protocols
SET name = 'Cloudflare WARP Egress',
    description = 'Cloudflare WARP client egress for AmneziaWG2 via a pool of WARP profiles (registered directly against the WARP API, no wgcf binary) with automatic rotation on error/429/traffic. Health-gated netns policy routing: AWG2 client TCP/UDP egress is routed through WARP only after a live trace check passes; the VPN handshake port stays direct and client configs are unchanged.',
    install_script   = FROM_BASE64(''),
    uninstall_script = FROM_BASE64(''),
    output_template  = FROM_BASE64('V0FSUCBjbGllbnQgZWdyZXNzIGZvciBBbW5lemlhV0cyIChwb29sICsgcm90YXRpb24pCk1vZGU6IHt7d2FycF9tb2RlfX0KQWN0aXZlIHByb2ZpbGU6IHt7d2FycF9hY3RpdmVfcHJvZmlsZX19ClBvb2wgc2l6ZToge3t3YXJwX3Bvb2xfc2l6ZX19ClJvdGF0aW9uczoge3t3YXJwX3JvdGF0aW9uc319CkV4aXQgSVA6IHt7d2FycF9pcH19ClN0YXR1czoge3t3YXJwX3N0YXR1c319Cg=='),
    definition = JSON_OBJECT(
      'engine', 'shell',
      'metadata', JSON_OBJECT(
        'container_name', 'amnezia-awg2',
        'target_protocol', 'awg2',
        'config_dir', '/opt/amnezia/awg2',
        'config_file', 'awg0.conf',
        'routes_client_egress', true,
        'routing_method', 'warp_wireguard_netns_pool_rotation_health_gated',
        'client_configs_unchanged', true,
        'routing_scope', 'tcp_udp_client_egress',
        'route_table', 51888,
        'mark', '0x2cf2',
        'warp_pool', true
      )
    ),
    updated_at = NOW()
WHERE slug = 'cf-warp';
